import { useEffect, useState } from "react";

export default function AdminOrders() {
  const [orders, setOrders] = useState([]);
  const [loading, setLoading] = useState(false);

  const API_BASE = "http://127.0.0.1:8000/api";

  // -----------------------------
  // Fetch orders from backend
  // -----------------------------
  const fetchOrders = async () => {
    try {
      setLoading(true);
      const res = await fetch(`${API_BASE}/orders/`);
      const data = await res.json();

      if (Array.isArray(data)) {
        setOrders(data);
      } else {
        setOrders([]);
      }
    } catch (err) {
      console.error("Failed to fetch orders", err);
    } finally {
      setLoading(false);
    }
  };

  // -----------------------------
  // Update order status (backend)
  // -----------------------------
  const updateStatus = async (order_id, status) => {
    try {
      await fetch(`${API_BASE}/orders/update-status/`, {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ order_id, status }),
      });

      // 🔥 Always reload from backend after update
      fetchOrders();
    } catch (err) {
      alert("Failed to update order status");
    }
  };

  // -----------------------------
  // Live polling every 3 seconds
  // -----------------------------
  useEffect(() => {
    fetchOrders();
    const interval = setInterval(fetchOrders, 3000);
    return () => clearInterval(interval);
  }, []);

  // -----------------------------
  // UI
  // -----------------------------
  return (
    <div className="admin-orders">
      <h3>Orders</h3>

      {loading && <p>Loading orders...</p>}

      {!loading && orders.length === 0 && <p>No orders yet.</p>}

      {orders.map((order) => (
        <div key={order.order_id} className="order-card">
          <h4>Order #{order.order_id}</h4>

          <p>
            User: <strong>{order.user}</strong>
          </p>

          <p>
            Total: ₹<strong>{order.total}</strong>
          </p>

          <p>
            Current Status:{" "}
            <strong style={{ textTransform: "capitalize" }}>
              {order.status}
            </strong>
          </p>

          <select
            value={order.status}
            onChange={(e) =>
              updateStatus(order.order_id, e.target.value)
            }
          >
            <option value="Pending">Pending</option>
            <option value="Ready">Ready</option>
            <option value="Completed">Completed</option>
          </select>

          <div className="order-items">
            <strong>Items:</strong>
            <ul>
              {Array.isArray(order.items) &&
                order.items.map((item, i) => (
                  <li key={i}>
                    {item.name} × {item.quantity}
                  </li>
                ))}
            </ul>
          </div>
        </div>
      ))}
    </div>
  );
}
